catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
	if (newValue=="yes"){
		if (g_lang == "fq"){
			g_form.setLabelOf('complainant_name','Votre nom');
			g_form.setLabelOf('complainant_manager','Votre gestionnaire ou superviseur');
			g_form.setLabelOf('complainant_phone_number','Votre numéro de téléphone préféré');
			g_form.setLabelOf('complainant_email_address','Votre adresse courriel préféré');
			g_form.setLabelOf('handled_by_complainant_manager','Votre gestionnaire ou superviseur');
		}
		else
		{
			g_form.setLabelOf('complainant_name','Your name');
			g_form.setLabelOf('complainant_manager','Your manager');
			g_form.setLabelOf('complainant_phone_number','Your preferred phone number');
			g_form.setLabelOf('complainant_email_address','Your preferred email address');
			g_form.setLabelOf('handled_by_complainant_manager','Your manager');		
		}
		//g_form.setLabelOf('defendant_name','');
		//g_form.setLabelOf('defendant_manager','');
		//g_form.setLabelOf('defendant_number','');
		//g_form.setLabelOf('defendant_address','');
	}
	else
	{
		if (g_lang == "fq"){

			g_form.setLabelOf('complainant_name','Nom de la partie principale');
			g_form.setLabelOf('complainant_manager','Gestionnaire de la partie principale');
			g_form.setLabelOf('complainant_phone_number','Numéro de téléphone de la partie principale');
			g_form.setLabelOf('complainant_email_address','Adresse courriel de la partie principale');
			g_form.setLabelOf('handled_by_complainant_manager','Gestionnaire ou superviseur de la partie principale');
		}
		else
		{
			g_form.setLabelOf('complainant_name','Principal party\'s name');
			g_form.setLabelOf('complainant_manager','Principal party\'s manager');
			g_form.setLabelOf('complainant_phone_number','Principal party\'s phone number');
			g_form.setLabelOf('complainant_email_address','Principal party\'s email address');
			g_form.setLabelOf('handled_by_complainant_manager','Principal party\'s manager');
		}
		//g_form.setLabelOf('defendant_name','');
		//g_form.setLabelOf('defendant_manager','');
		//g_form.setLabelOf('defendant_number','');
		//g_form.setLabelOf('defendant_address','');
	}

   //Type appropriate comment here, and begin script below

}
